text.value:
Sure, I can help you create a new script that checks a list of strings instead of digits. This script will allow you to specify the list of correct strings in the Unity Inspector.

Here's the modified script:

```c#
using System;
using Screens.Bases;
using TMPro;
using Unity.VisualScripting;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using ColorUtility = UnityEngine.ColorUtility;

namespace Screens
{
    public class Screen8StringCheck : ScreenBase
    {
        private InputField[] inputFields = new InputField[3];
        [SerializeField] private string[] correctStrings = new string[3];
        [SerializeField] private GameObject failedGO;

        protected override void Start()
        {
            Init();
        }

        private void Init()
        {
            base.Start();
            inputFields = GetComponentsInChildren<InputField>();

            for (int i = 0; i < inputFields.Length; i++)
            {
                inputFields[i].characterLimit = 1;
                int i1 = i;
                inputFields[i].onValueChanged.AddListener(delegate(string text) { OnFieldValueChanged(i1, text); });
                inputFields[i].onEndEdit.AddListener(delegate(string text) { OnFieldValueChanged(i1, text); });
            }
        }

        private void OnFieldValueChanged(int i, string text)
        {
            // if(string.IsNullOrEmpty(text) && i > 0)
            // {
            //     inputFields[i - 1].Select();
            // }
            // else if (i < inputFields.Length - 1 && text != "")
            // {
            //     inputFields[i + 1].Select();
            //     
            // }
        }

        private void Update()
        {
            IsCodeCorrect();
        }

        private void IsCodeCorrect()
        {
            // Check if all fields are filled
            foreach (InputField inputField in inputFields)
            {
                if (inputField.text == "")
                {
                    DeactivateFailedMessage();
                    return;
                }
            }

            bool isCodeCorrect = true;
            for (int i = 0; i < inputFields.Length; i++)
            {
                if (inputFields[i].text != correctStrings[i])
                {
                    isCodeCorrect = false;
                }
            }

            if (isCodeCorrect)
            {
                DeactivateFailedMessage();
                EventManager.AssignmentCompleted.Invoke();
            }
            else
            {
                ActivateFailedMessage();
            }
        }

        private void DeactivateFailedMessage()
        {
            failedGO.SetActive(false);
            // Change color of input fields
            foreach (InputField inputField in inputFields)
            {
                inputField.image.color = Color.white;
            }
        }

        private void ActivateFailedMessage()
        {
            failedGO.SetActive(true);
            foreach (InputField inputField in inputFields)
            {
                bool parseSuccess = ColorUtility.TryParseHtmlString("#FF4050", out Color newCol);
                inputField.image.color = newCol;
            }
        }
    }
}
```

In this script, the `correctStrings` array is serialized, allowing you to set the correct strings in the Unity Inspector. The `IsCodeCorrect` method now checks the input fields against these strings instead of digits.

The provided script checks the input fields for correctness in the `Update` method, which means it will continuously check the input fields every frame. If you want to check the input fields immediately after a change, you should move the check to the `OnFieldValueChanged` method.

Here's the updated script that checks the input fields immediately after a change:

```c#
using System;
using Screens.Bases;
using TMPro;
using Unity.VisualScripting;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using ColorUtility = UnityEngine.ColorUtility;

namespace Screens
{
    public class Screen8StringCheck : ScreenBase
    {
        private InputField[] inputFields = new InputField[3];
        [SerializeField] private string[] correctStrings = new string[3];
        [SerializeField] private GameObject failedGO;

        protected override void Start()
        {
            Init();
        }

        private void Init()
        {
            base.Start();
            inputFields = GetComponentsInChildren<InputField>();

            for (int i = 0; i < inputFields.Length; i++)
            {
                inputFields[i].characterLimit = 1;
                int i1 = i;
                inputFields[i].onValueChanged.AddListener(delegate(string text) { OnFieldValueChanged(i1, text); });
                inputFields[i].onEndEdit.AddListener(delegate(string text) { OnFieldValueChanged(i1, text); });
            }
        }

        private void OnFieldValueChanged(int i, string text)
        {
            IsCodeCorrect();
        }

        private void IsCodeCorrect()
        {
            // Check if all fields are filled
            foreach (InputField inputField in inputFields)
            {
                if (inputField.text == "")
                {
                    DeactivateFailedMessage();
                    return;
                }
            }

            bool isCodeCorrect = true;
            for (int i = 0; i < inputFields.Length; i++)
            {
                if (inputFields[i].text != correctStrings[i])
                {
                    isCodeCorrect = false;
                }
            }

            if (isCodeCorrect)
            {
                DeactivateFailedMessage();
                EventManager.AssignmentCompleted.Invoke();
            }
            else
            {
                ActivateFailedMessage();
            }
        }

        private void DeactivateFailedMessage()
        {
            failedGO.SetActive(false);
            // Change color of input fields
            foreach (InputField inputField in inputFields)
            {
                inputField.image.color = Color.white;
            }
        }

        private void ActivateFailedMessage()
        {
            failedGO.SetActive(true);
            foreach (InputField inputField in inputFields)
            {
                bool parseSuccess = ColorUtility.TryParseHtmlString("#FF4050", out Color newCol);
                inputField.image.color = newCol;
            }
        }
    }
}
```

In this updated script, the `IsCodeCorrect` method is called inside the `OnFieldValueChanged` method. This ensures that the input fields are checked for correctness immediately after any change.
